PRAGMA foreign_keys = OFF;
CREATE TABLE "DryCleanOrder_new" (id TEXT PRIMARY KEY, orderNumber INTEGER NOT NULL UNIQUE, clientId TEXT NOT NULL, deliveryAddress TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'received', receivedByEmployeeId TEXT NOT NULL, assignedIronerId TEXT, deliveredByEmployeeId TEXT, receivedAt TEXT NOT NULL, expectedDeliveryAt TEXT, processingStartedAt TEXT, completedAt TEXT, readyAt TEXT, deliveredAt TEXT, cancelledAt TEXT, cancelledReason TEXT, subtotal REAL NOT NULL DEFAULT 0, discountAmount REAL NOT NULL DEFAULT 0, totalAmount REAL NOT NULL DEFAULT 0, notes TEXT, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, FOREIGN KEY (clientId) REFERENCES Client(id), FOREIGN KEY (receivedByEmployeeId) REFERENCES Employee(id), FOREIGN KEY (assignedIronerId) REFERENCES Employee(id), FOREIGN KEY (deliveredByEmployeeId) REFERENCES Employee(id), CHECK (status IN ('received', 'prepared', 'delivered', 'cancelled')), CHECK (subtotal >= 0), CHECK (discountAmount >= 0), CHECK (totalAmount >= 0));
INSERT INTO DryCleanOrder_new (id,orderNumber,clientId,deliveryAddress,status,receivedByEmployeeId,assignedIronerId,deliveredByEmployeeId,receivedAt,expectedDeliveryAt,processingStartedAt,completedAt,readyAt,deliveredAt,cancelledAt,cancelledReason,subtotal,discountAmount,totalAmount,notes,createdAt,updatedAt) SELECT id,orderNumber,clientId,deliveryAddress,CASE WHEN status IN ('processing', 'needs_review', 'ready') THEN 'prepared' ELSE status END,receivedByEmployeeId,assignedIronerId,deliveredByEmployeeId,receivedAt,expectedDeliveryAt,processingStartedAt,completedAt,readyAt,deliveredAt,cancelledAt,cancelledReason,subtotal,discountAmount,totalAmount,notes,createdAt,updatedAt FROM DryCleanOrder;
DROP TABLE DryCleanOrder;
ALTER TABLE DryCleanOrder_new RENAME TO DryCleanOrder;
CREATE INDEX idx_dry_clean_order_client ON DryCleanOrder(clientId, createdAt);
CREATE INDEX idx_dry_clean_order_status ON DryCleanOrder(status, expectedDeliveryAt);
UPDATE DryCleanOrderStatusHistory SET fromStatus = CASE WHEN fromStatus IN ('processing', 'needs_review', 'ready') THEN 'prepared' ELSE fromStatus END, toStatus = CASE WHEN toStatus IN ('processing', 'needs_review', 'ready') THEN 'prepared' ELSE toStatus END;
PRAGMA foreign_keys = ON;
